/* =================================
   Room Lobby
   ================================= */

.lobby-shell {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 560px;
  margin: 0 auto;
  padding: 1.25rem 1.25rem 2rem;
  animation: fade-in var(--duration-normal) var(--ease-out) both;
}

.lobby-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0 1.25rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 1.25rem;
}

.lobby-title {
  margin: 0;
  flex: 1;
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 300;
  letter-spacing: -0.03em;
  color: var(--text);
}

.lobby-user {
  font-family: var(--mono);
  font-size: 0.62rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

/* === Room Rail Toolbar === */

.room-toolbar {
  display: flex;
  gap: 0.35rem;
  padding: 0.25rem 1rem 0.5rem;
  flex-shrink: 0;
}

.room-toolbar input {
  flex: 1;
  min-width: 0;
  padding: 0.45rem 0.65rem;
  font-size: 0.8125rem;
}

.room-toolbar .secondary-btn {
  flex-shrink: 0;
  font-size: 0.75rem;
  padding: 0.45rem 0.75rem;
}

/* === Swipe-to-Reveal Delete === */

.room-swipe-wrap {
  display: flex;
  align-items: stretch;
  width: 100%;
  overflow: visible;
  position: relative;
  transition: transform var(--duration-fast) var(--ease-out);
  touch-action: pan-y;
  user-select: none;
}

.room-swipe-delete {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--error);
  color: #ffffff;
  border: none;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  cursor: pointer;
  font: inherit;
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  opacity: 0;
  transition: opacity var(--duration-fast) ease;
  pointer-events: none;
  z-index: 1;
}

.room-swipe-delete:active {
  background: #c41e2b;
}

.room-swipe-wrap .room-row {
  position: relative;
  z-index: 2;
  width: 100%;
  flex: 1;
}

/* === Room List === */

.room-list {
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1;
