			function commitSwipe(dx: number): void {
				if (dx < -SWIPE_THRESHOLD / 2) {
					// Open delete
					swipeWrap.style.transform = `translateX(-${SWIPE_THRESHOLD}px)`;
					deleteAction.style.opacity = "1";
